files.content:
.toast-region{
  position:fixed;
  right:var(--s-6);
  bottom:var(--s-6);
  z-index:var(--z-toast);
  display:flex;
  flex-direction:column;
  gap:var(--s-3);
  width:min(var(--w-toast), calc(100vw - var(--s-8)));
  pointer-events:none;
}
.toast{
  pointer-events:auto;
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  column-gap:var(--s-3);
  row-gap:var(--s-1);
  align-items:center;
  padding:var(--s-4);
  background:var(--obsidian-850);
  border:var(--bw-1) solid var(--obsidian-700);
  border-left:var(--bw-2) solid var(--primary-500);
  border-radius:var(--r-md);
  box-shadow:var(--sh-3);
  font-size:var(--t-small);
  color:var(--obsidian-200);
  opacity:0;
  transform:translateX(24px);
  transition:opacity var(--d-base) var(--ease-decel), transform var(--d-base) var(--ease-decel);
}
.toast.is-in{
  opacity:1;
  transform:translateX(0);
}
.toast-icon{
  grid-column:1;
  grid-row:1;
  width:var(--icon-sm);
  height:var(--icon-sm);
  color:var(--primary-400);
}
.toast-title{
  grid-column:2;
  grid-row:1;
  font-weight:600;
  color:var(--obsidian-100);
  min-width:0;
}
.toast-body{
  grid-column:2;
  grid-row:1;
  min-width:0;
  overflow-wrap:anywhere;
}
.toast:has(.toast-title) .toast-body{
  grid-column:1 / -1;
  grid-row:2;
}
.toast-action{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--primary-400);
  background:transparent;
  border:0;
  cursor:pointer;
  padding:var(--s-1) 0;
  margin-top:var(--s-2);
  transition:color var(--d-quick) var(--ease-standard);
}
.toast-action:hover{
  color:var(--primary-300);
}
.toast-action:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--focus-offset);
  box-shadow:var(--ring-halo);
}
.toast-dismiss{
  grid-column:3;
  grid-row:1;
  display:grid;
  place-items:center;
  width:20px;
  height:20px;
  color:var(--obsidian-400);
  border-radius:var(--r-sm);
  background:transparent;
  border:0;
  cursor:pointer;
  transition:color var(--d-quick) var(--ease-standard), background var(--d-quick) var(--ease-standard);
}
.toast-dismiss:hover{
  color:var(--obsidian-100);
  background:var(--obsidian-800);
}
.toast-dismiss:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--s-px);
  box-shadow:var(--ring-halo);
}
.toast-dismiss svg{
  width:var(--icon-xs);
  height:var(--icon-xs);
}
.toast-success{
  border-left-color:var(--success);
}
.toast-success .toast-icon{
  color:var(--success);
}
.toast-warn{
  border-left-color:var(--warning);
}
.toast-warn .toast-icon{
  color:var(--warning);
}
.toast-danger{
  border-left-color:var(--danger);
}
.toast-danger .toast-icon{
  color:var(--danger);
}
@media (max-width:480px){
  .toast-region{
    left:var(--s-4);
    right:var(--s-4);
    bottom:var(--s-4);
    width:auto;
  }
}
.toast{
  width:min(100%, calc(var(--s-32) * 2.5));
}
